public:
    int strongPasswordChecker(string password) {
        int n = password.size();
        bool hasLower = false, hasUpper = false, hasDigit = false;
        for (char c : password) {
            if (islower(c)) hasLower = true;
            else if (isupper(c)) hasUpper = true;
            else if (isdigit(c)) hasDigit = true;
        }
        int missing = (!hasLower) + (!hasUpper) + (!hasDigit);
        int replace = 0, oneDel = 0, twoDel = 0;

        int i = 2;
        while (i < n) {
            if (password[i] == password[i - 1] && password[i - 1] == password[i - 2]) {
                int len = 2;
                while (i < n && password[i] == password[i - 1]) {
                    len++;
                    i++;
                }
                replace += len / 3;
                if (len % 3 == 0) oneDel++;
                else if (len % 3 == 1) twoDel++;
            } else {
                i++;
            }
        }

        if (n < 6) {
            return max(6 - n, missing);
        } else if (n <= 20) {
            return max(replace, missing);
        } else {
            int toDelete = n - 20;
            replace -= min(toDelete, oneDel);
            replace -= min(max(toDelete - oneDel, 0) / 2, twoDel);
            replace -= max(toDelete - oneDel - 2 * twoDel, 0) / 3;
