class Solution {
    public int strongPasswordChecker(String password) {
        int n = password.length();
        boolean hasLower = false, hasUpper = false, hasDigit = false;
        for (int i = 0; i < n; i++) {
            char c = password.charAt(i);
            if (Character.isLowerCase(c)) hasLower = true;
            else if (Character.isUpperCase(c)) hasUpper = true;
            else if (Character.isDigit(c)) hasDigit = true;
        }
        int missing = (hasLower ? 0 : 1) + (hasUpper ? 0 : 1) + (hasDigit ? 0 : 1);
        int replace = 0, oneDel = 0, twoDel = 0;

        int i = 2;
        while (i < n) {
            if (password.charAt(i) == password.charAt(i - 1) && password.charAt(i - 1) == password.charAt(i - 2)) {
                int len = 2;
                while (i < n && password.charAt(i) == password.charAt(i - 1)) {
                    len++;
                    i++;
                }
                replace += len / 3;
                if (len % 3 == 0) oneDel++;
                else if (len % 3 == 1) twoDel++;
            } else {
                i++;
            }
        }

        if (n < 6) {
            return Math.max(6 - n, missing);
        } else if (n <= 20) {
            return Math.max(replace, missing);
        } else {
            int toDelete = n - 20;
            replace -= Math.min(toDelete, oneDel);
            replace -= Math.min(Math.max(toDelete - oneDel, 0) / 2, twoDel);
            replace -= Math.max(toDelete - oneDel - 2 * twoDel, 0) / 3;
            return toDelete + Math.max(replace, missing);
        }
    }
}

var strongPasswordChecker = function(password) {
    const n = password.length;
    let hasLower = false, hasUpper = false, hasDigit = false;
    for (let i = 0; i < n; i++) {
        const c = password[i];
        if (c >= "a" && c <= "z") hasLower = true;
        else if (c >= "A" && c <= "Z") hasUpper = true;
        else if (c >= "0" && c <= "9") hasDigit = true;
    }
    const missing = (!hasLower ? 1 : 0) + (!hasUpper ? 1 : 0) + (!hasDigit ? 1 : 0);
    let replace = 0, oneDel = 0, twoDel = 0;

    let i = 2;
    while (i < n) {
        if (password[i] === password[i - 1] && password[i - 1] === password[i - 2]) {
            let len = 2;
            while (i < n && password[i] === password[i - 1]) {
                len++;
                i++;
            }
            replace += Math.floor(len / 3);
            if (len % 3 === 0) oneDel++;
            else if (len % 3 === 1) twoDel++;
        } else {
            i++;
        }
    }

    if (n < 6) {
        return Math.max(6 - n, missing);
    } else if (n <= 20) {
        return Math.max(replace, missing);
    } else {
        const toDelete = n - 20;
        replace -= Math.min(toDelete, oneDel);
        replace -= Math.min(Math.floor(Math.max(toDelete - oneDel, 0) / 2), twoDel);
        replace -= Math.floor(Math.max(toDelete - oneDel - 2 * twoDel, 0) / 3);
        return toDelete + Math.max(replace, missing);
    }
};
